  response: string;
  primary_agent: PatAgent;
  contributing_agents?: PatAgent[];
  session_id?: string;
  poi_generated?: number;
  latency_ms: number;
  ihsan_score: number;
  backend_used: 'ollama' | 'lmstudio';
}

